-- DIGIT HR handoff: move the seven unpublished HR drafts to the handoff route slugs and seed their source-backed content.
with src(old_path, slug, title_ar, title_en, desc_ar, desc_en, head_ar, head_en, refs) as (values
('/hr/core-hr','core-hr','الموارد البشرية الأساسية والهيكل التنظيمي | DIGIT HR','Core HR & Organization | DIGIT HR','من الهيكل التنظيمي والمناصب إلى ملف الموظف والتعيين والعقد؛ مرجع واحد يمنح كل عملية سياقها.','From organizational structure and positions to employee records, appointments and contracts—one reference gives every process its context.','كل قرار يبدأ من ملف موثوق','Every decision starts with a trusted record',array['01.1','01.2','01.3','01.4','01.5','01.6']),
('/hr/talent','talent-hcm','المواهب ورأس المال البشري | DIGIT HR','Talent & Human Capital | DIGIT HR','من طلب الاحتياج والاستقطاب إلى المقابلة والعرض والتهيئة والأداء والتعلم والتعاقب الوظيفي.','From staffing requests and sourcing to interviews, offers, onboarding, performance, learning and succession.','الموهبة رحلة، وليست ملف مرشح','Talent is a journey, not a candidate file',array['02.1','02.2','02.3','02.4','02.5']),
('/hr/workforce','workforce-management','إدارة القوى العاملة | DIGIT HR','Workforce Management | DIGIT HR','الإجازات والحضور والورديات والساعات الإضافية ومصادر الوقت، ضمن مشهد واحد قابل للمراجعة.','Leave, attendance, shifts, overtime and time data sources in one reviewable view.','افهم يوم العمل قبل احتساب أثره','Understand the workday before calculating its impact',array['03.1','03.2','03.3','03.4']),
('/hr/payroll','payroll-rewards','الرواتب والمكافآت والمزايا | DIGIT HR','Payroll & Rewards | DIGIT HR','من جاهزية بيانات المسير إلى حساب الاستحقاقات والاستثناءات والاعتماد وأثر الصرف، دون خلط المراحل.','From payroll run data readiness to accrual calculations, exceptions, approval and disbursement impact, with each stage kept distinct.','الرواتب عملية مراجعة قبل أن تكون كشفًا','Payroll is a review process before it is a register',array['04.1','04.2','04.3','04.4','04.5']),
('/hr/self-service','employee-experience','تجربة الموظف والمدير | DIGIT HR','Employee & Manager Experience | DIGIT HR','خدمة ذاتية واضحة، موافقة من مسؤول معلوم، وحالة يمكن للموظف متابعتها حتى الإغلاق.','Clear self-service, approval by a clearly identified owner, and a status employees can track through to closure.','الطلب لا ينتهي عند الضغط على إرسال','A request does not end when you hit submit',array['05.1','05.2','05.3']),
('/hr/people-analytics','people-intelligence','ذكاء الموارد البشرية والتخطيط | DIGIT HR','People Intelligence & Planning | DIGIT HR','مراكز قيادة، تخطيط للوظائف والتكاليف، وتحليلات قابلة للتصفية والرجوع إلى سجلاتها.','Command centers, job and cost planning, and analytics that can be filtered and traced back to their records.','كل مؤشر يبدأ بسؤال وينتهي بمصدر','Every indicator starts with a question and ends with a source',array['06.1','06.2','06.3']),
('/hr/administration','administration-governance','الإعدادات والحوكمة | DIGIT HR','Administration & Governance | DIGIT HR','التأسيس والخصوصية وسياق الوصول والإشعارات والمراقبة؛ عناصر تحمي صحة العمل وثقة المستخدم.','Setup, privacy, access context, notifications and monitoring protect operational integrity and user trust.','الثقة تبدأ من حدود الصلاحية','Trust starts with clear permission boundaries',array['07.1','07.2','07.3','07.4'])
), blocks as (
  select slug, (select jsonb_agg(jsonb_build_object('id', 'src-' || replace(r, '.', '-'), 'type', 'source', 'ref', r, 'title', '', 'body', '', 'shotId', '', 'mediaUrl', '', 'mediaAlt', '', 'href', '', 'enabled', true, 'eyebrow', '', 'items', '[]'::jsonb, 'shots', '[]'::jsonb, 'focus', null) order by o) from unnest(refs) with ordinality as t(r, o)) as b
  from src
)
update public.cms_documents d set
  path = '/hr/' || s.slug,
  draft = jsonb_set(jsonb_set(jsonb_set(d.draft,
    '{department,id}', to_jsonb(s.slug)),
    '{ar}', (d.draft->'ar') || jsonb_build_object('title', s.title_ar, 'description', s.desc_ar, 'headline', s.head_ar, 'lede', s.desc_ar, 'blocks', b.b)),
    '{en}', (d.draft->'en') || jsonb_build_object('title', s.title_en, 'description', s.desc_en, 'headline', s.head_en, 'lede', s.desc_en, 'blocks', b.b)),
  updated_at = now()
from src s join blocks b using (slug)
where d.path = s.old_path and d.published is null and d.kind = 'department';